import{_ as s,o as t,c as i,a2 as a}from"./chunks/framework.CcJ8wlZS.js";const k=JSON.parse('{"title":"Behavior Evals","description":"Golden corpus, behavior fixtures, stability, PR replay, real-repo evals","frontmatter":{"type":"index","title":"Behavior Evals","description":"Golden corpus, behavior fixtures, stability, PR replay, real-repo evals","created":"2026-09-19T00:00:00.000Z","updated":"2026-09-19T00:00:00.000Z"},"headers":[],"relativePath":"evals.md","filePath":"evals.md"}'),n={name:"evals.md"};function l(o,e,r,d,h,p){return t(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="behavior-evals-does-the-fabric-change-agent-behavior" tabindex="-1">Behavior Evals: Does the Fabric Change Agent Behavior? <a class="header-anchor" href="#behavior-evals-does-the-fabric-change-agent-behavior" aria-label="Permalink to &quot;Behavior Evals: Does the Fabric Change Agent Behavior?&quot;">​</a></h1><p>The compiler evals (<code>eval.py</code>, golden corpus) measure extraction quality. <strong>Behavior evals</strong> measure the thing that actually matters: when an agent receives the context manifest, does it make a better decision?</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-behavior.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # zero-LLM: manifest-level compliance (CI)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-behavior.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --llm</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # probe a real model + score its answer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-behavior.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --record</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> # append metrics to registry/log.md</span></span></code></pre></div><p>Fixtures in <code>evaluations/behavior/</code> encode scenarios with two layers:</p><ol><li><strong>Zero-LLM layer (deterministic):</strong> does the compiled manifest deliver the required knowledge? — banned anti-pattern present in the prompt, binding decision present, stale pattern excluded with a reason, gap acknowledged (nothing selected where no knowledge exists).</li><li><strong>LLM layer (<code>--llm</code>):</strong> the same fixture&#39;s probe question is sent to a real model <em>with</em> the manifest; the answer must contain the compliant behavior (<code>must_contain</code>) and must not contain the banned approach (<code>must_not_contain</code>).</li></ol><p>Current fixtures:</p><table tabindex="0"><thead><tr><th>Fixture</th><th>Behavior tested</th></tr></thead><tbody><tr><td><code>be1-avoid-anti-pattern</code></td><td>agent is told NOT to build the banned shared token cache; implements rotation + per-session</td></tr><tr><td><code>be2-project-over-global</code></td><td>project constraint (rotating tokens) beats the general preference (session store)</td></tr><tr><td><code>be3-stale-demoted</code></td><td>stale pattern excluded from the manifest, fresh pattern delivered</td></tr><tr><td><code>be4-escalate-gap</code></td><td>no billing knowledge exists → agent escalates rather than inventing policy</td></tr></tbody></table><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Knowledge Utility: 100% (4/4)</span></span></code></pre></div><p><strong>Knowledge Utility</strong> = fixtures whose required knowledge was delivered ÷ total. Regression guard: CI fails if any fixture stops passing — the same discipline as the compiler evals, applied to behavior. This is the differentiator: repos that only promise &quot;compounding memory&quot; can&#39;t measure whether the memory changed anything.</p><h3 id="real-repo-evaluation" tabindex="-1">Real-repo evaluation <a class="header-anchor" href="#real-repo-evaluation" aria-label="Permalink to &quot;Real-repo evaluation&quot;">​</a></h3><p>For a heavyweight end-to-end check, run the whole pipeline against a real, popular repo (default: FastAPI — large, active, well-documented Python):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-real-repo.py</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                      # clone + full pipeline + LLM ingest</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-real-repo.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-llm</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # corpus + context metrics, no LLM</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-real-repo.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/clone</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-real-repo.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>It seeds a throwaway fabric with both integrations enabled, captures a scoped slice of the repo&#39;s docs, ingests with LLM claim extraction (or seeds doc-backed patterns in <code>--skip-llm</code> mode), compiles probe-task manifests, and measures each tier:</p><table tabindex="0"><thead><tr><th>Tier</th><th>Metric</th></tr></thead><tbody><tr><td>Corpus</td><td>sources captured, claims extracted, locator rate, lint errors</td></tr><tr><td>Context</td><td>manifest hit-rate per probe task (selected &gt; 0 with reasons)</td></tr><tr><td>Graphify</td><td>AST symbols indexed from the real repo (e.g. 4,992 for FastAPI), entity pages written</td></tr><tr><td>Embeddings</td><td>re-rank delta when <code>sentence-transformers</code> is installed; reported as config-only when absent</td></tr></tbody></table><p>The graphify/embeddings tiers are measured <em>as integrations</em>: their contribution is reported separately, so you can see exactly what enabling them buys.</p><h3 id="pr-replay-evaluation" tabindex="-1">PR replay evaluation <a class="header-anchor" href="#pr-replay-evaluation" aria-label="Permalink to &quot;PR replay evaluation&quot;">​</a></h3><p>Replay <strong>real PRs</strong> from an active repo and measure whether the fabric would have helped when the PR was written — a knowledge-recall eval on real-world vocabulary:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-pr-replay.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiangolo/fastapi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --prs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 16192</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --llm</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-pr-replay.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --repo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tiangolo/fastapi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --auto</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # pick recent merged PRs (deps-bumps skipped)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-pr-replay.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ...</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span></span></code></pre></div><p>Per replayed PR (fetched live via <code>gh</code> — title, body, review comments, touched files):</p><ul><li><strong>Graphify tier:</strong> the repo&#39;s code is AST-indexed; the report shows entity pages written and how many of the PR&#39;s touched files have code-symbol coverage (e.g. 4,992 symbols / 913 pages from FastAPI; 1/2 touched files covered).</li><li><strong>Zero-LLM tier:</strong> manifest hit-rate over docs-only corpus (honest baseline).</li><li><strong><code>--llm</code> tier:</strong> the PR&#39;s own discussion is ingested with LLM claim extraction; the manifest re-compiles and the report shows <code>after LLM ingest (12 claims): coverage 0.414 (Δ +0.414)</code> — how much the PR&#39;s own knowledge improves later recall of its task.</li></ul><p><strong>Term coverage</strong> = share of the PR&#39;s own vocabulary (title + body + comments, stemmed) present in the selected artifacts — a recall proxy on real work. The coverage delta isolates the value of the ingest step itself.</p><h3 id="stability-sensitivity-evaluation" tabindex="-1">Stability &amp; sensitivity evaluation <a class="header-anchor" href="#stability-sensitivity-evaluation" aria-label="Permalink to &quot;Stability &amp; sensitivity evaluation&quot;">​</a></h3><p>Closes the rubric&#39;s reproducibility rows with hard gates:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-stability.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skip-llm</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # deterministic gates (CI)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-stability.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --models</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> qwen2.5-coder:7b,qwen3.8:27b-mlx</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/eval-stability.py</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --record</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # append metrics to registry/log.md</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Gate</th><th>What it proves</th><th>Threshold</th></tr></thead><tbody><tr><td>G1 context determinism</td><td>20 manifest runs byte-identical</td><td>exact (0-token code must not vary)</td></tr><tr><td>G2 rebuild determinism</td><td><code>rebuild-index</code> output identical across runs</td><td>exact</td></tr><tr><td>G3 ingest stability</td><td>same model, same source, 2 runs</td><td>fuzzy word-coverage ≥ 0.7 (exact Jaccard reported; paraphrase ≠ instability)</td></tr><tr><td>G6 locator presence</td><td>every claim carries an L-locator</td><td>1.0</td></tr><tr><td>G4 model sensitivity</td><td>two models on the same source</td><td>fuzzy ≥ 0.5 (target 0.8); a fail means model swap requires re-running compiler evals</td></tr></tbody></table><p><strong>Live findings</strong> (recorded in <code>registry/log.md</code>): context/rebuild are exactly deterministic (~40ms); same-model extraction is semantically stable (fuzzy 0.76–0.86) but drifts in wording (exact 0.31–0.73). A <strong>5-model matrix</strong> — local (qwen2.5-coder:7b, qwen3.8:27b-mlx) vs Ollama cloud (deepseek-v4.1-flash:cloud, kimi-k2.7-code:cloud, glm-5.3-flash:cloud) — first showed capability-correlated disagreement (fuzzy 0.28–0.59). Fixing it took a contract change, not a model change: the CLAIM_PROMPT now carries an explicit <strong>granularity spec</strong> (exactly one verifiable fact per claim, target 5–12). After that: <strong>all 10 pairwise G4 checks PASS (fuzzy 0.75–0.85)</strong> and claim counts converge to 11–12 across every model. The compiler change was re-baselined against the golden corpus first (recall 0.89, locator 1.00 — PASS). Infra note: cloud reasoning models can silently return 0 claims when reasoning consumes the token budget — the extractor now budgets 16K tokens and retries on <code>finish_reason=length</code>.</p><h3 id="model-policy-ops-vs-compiler-models" tabindex="-1">Model policy: ops vs compiler models <a class="header-anchor" href="#model-policy-ops-vs-compiler-models" aria-label="Permalink to &quot;Model policy: ops vs compiler models&quot;">​</a></h3><p>Claim extraction is <em>compiler work</em> — it compiles sources into the fabric&#39;s canonical evidence — so it runs on a policy-designated <strong>compiler model</strong>, not whatever model is configured for cheap queries:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Used for</th></tr></thead><tbody><tr><td><code>llm.model</code></td><td><code>qwen2.5-coder:7b</code></td><td>ops: capture, status, cheap query synthesis</td></tr><tr><td><code>llm.compiler_model</code></td><td><code>deepseek-v4.1-flash:cloud</code></td><td>claim extraction (<code>ingest --extract-claims</code>), synthesis, promotion mining</td></tr><tr><td><code>llm.local_model</code></td><td>platform-split: <code>mlx-community/gemma-4-e4b-it-4bit</code> (Apple Silicon) / <code>unsloth/gemma-4-e4b-it-GGUF</code> (other)</td><td>resolves <code>repos.&lt;slug&gt;.&lt;stage&gt;: local</code> routes — extraction, synthesis, dossier generation on-device</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Override per-run (e.g. test a different compiler model):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WIKI_LLM_COMPILER_MODEL</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">kimi-k2.7-code:cloud</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ingest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> evidence/raw/</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">do</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --extract-claims</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Check the local model is cached; offers a human-gated download when missing:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> models</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ensure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [--yes]      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># --check exits 0/1 without prompting (for scripts)</span></span></code></pre></div><p><strong>Local routes:</strong> <code>repos.&lt;slug&gt;.extract/synthesize/dossier: &quot;local&quot;</code> runs that stage on-device (privacy tiering). The backend is picked from the model id — GGUF (llama-cpp-python, universal — works on macOS/Linux/Windows) or MLX (mlx-lm, Apple Silicon only). Chat-tuned GGUF models (gemma etc.) run through their chat template automatically. Missing models are offered for download at first use (only the preferred quantization split is fetched, ~4 GB), or pre-fetch with <code>wf models ensure</code>. Install the backends with <code>pip install -e &quot;.[local]&quot;</code>. GGUF is the recommended testing default: one model format runs identically on every platform.</p><p><strong>The gate:</strong> <code>promote.py</code> and <code>mine-promotions.py</code> <strong>refuse to run</strong> unless <code>registry/log.md</code> contains a recorded compiler eval for the current compiler model. This enforces the G4 lesson — model swaps are compiler changes, and compiler changes require re-evaluation — as a hard gate instead of a docs sentence. <code>wf status</code> shows all three models (ops, compiler, local).</p><hr>`,33)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
